from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    """Return a (step, param) pair for the given name string.

    * ``"upper"`` → (Upper instance, None)
    * ``"truncate:3"`` → (Truncate instance, 3)
    * bare ``"truncate"`` or unknown name → raises ValueError / KeyError
    """
    if ":" in name:
        base, arg = name.split(":", 1)
    else:
        base, arg = name, None

    if base not in STEPS:
        raise KeyError(f"no step named {base!r}. Known: {', '.join(sorted(STEPS))}")

    step = STEPS[base]

    # Parameterised steps need an argument
    if isinstance(step, Truncate):
        if arg is None:
            raise ValueError(
                f"step {base!r} requires a length argument, "
                f"e.g. {base!}:3"
            )
        try:
            length = int(arg)
        except ValueError:
            raise ValueError(
                f"step {base!r} length must be an integer, got {arg!r}"
            )
        return (Truncate(length), None)

    if arg is not None:
        raise ValueError(
            f"step {base!r} does not take arguments, but got {arg!r}"
        )

    return (step, None)

